def recencia_dias(pedidos_cliente, data_ref):
    anteriores = [p for p in pedidos_cliente if p.data_pedido < data_ref]
    if not anteriores:
        return None
    ultimo = max(p.data_pedido for p in anteriores)
    return (data_ref - ultimo).days

SELECT COUNT(*) AS linhas_com_vazamento
FROM features_churn
WHERE recencia_dias < 0;
